from scirel.fusion import initialize_dcx_halo_marker
def plasma(position):
    return {'plasma_rotation_cm_s': [0.0, 0.0, 0.0], 'ion_temperature_kev': 2.0,
            'thermal_ion_density_cm3': [3.0, 5.0], 'thermal_mass_amu': [1.0, 2.0]}
def rates(position, velocity):
    return [1.0, 2.0, 0.0, 0.0, 0.0, 0.0]
result = initialize_dcx_halo_marker({
    'cell_center_cm': [10.0, 0.0, 0.0], 'cell_width_cm': [2.0, 2.0, 2.0],
    'uniform_draws': [0.5, 0.5, 0.5], 'plasma_state_provider': plasma,
    'standard_normal_draw': [0.0, 0.0, 0.0], 'selected_thermal_species_index': 1,
    'beam_mass_amu': 2.0, 'fast_ion_density_cm3': 7.0,
    'velocity_squared_to_kev_per_amu': 1.0e-12, 'cx_rate_provider': rates})
assert result['diagnostics']['graph_order'][-1] == 'initial_state'
assert result['eligible'] and abs(result['photon_fast_ion_correction'] - 5.0/12.0) < 1e-15
try:
    initialize_dcx_halo_marker({**{k: v for k, v in result.items()}})
except (ValueError, TypeError, KeyError):
    pass
else:
    raise AssertionError('a non-mapping inputs contract must fail')
