    initialize_dcx_halo_marker({'cell_center_cm': [10.0, 0.0, 0.0], 'cell_width_cm': [2.0, 2.0, 2.0], 'uniform_draws': [0.5, 0.5, 0.5], 'plasma_state_provider': plasma, 'standard_normal_draw': [0.0, 0.0, 0.0], 'selected_thermal_species_index': 1, 'beam_mass_amu': 2.0, 'fast_ion_density_cm3': 7.0, 'velocity_squared_to_kev_per_amu': 1.0e-12})
except ValueError:
    pass
else:
    raise AssertionError('a missing cx_rate_provider must fail closed')
